window.addEventListener('DOMContentLoaded',()=>{'use strict';
const $=id=>document.getElementById(id),stage=$('exchange-stage');if(!stage)return;const C=GlyphFlow.core,M=GlyphExchangeModel,source=$('exchange-field'),archive=$('exchange-archive'),definitions=M.definitions();source.definition=definitions.source;archive.definition=definitions.archive;
let directory,sourceEndpoint,archiveEndpoint,sourcePeer,archivePeer,lastRequest=null,queue=Promise.resolve(),active=0,disposed=false;const completions=new Map(),trace=[];
function log(entry){trace.push({...entry,step:trace.length+1});if(trace.length>100)trace.shift();$('exchange-log').textContent=trace.map(e=>String(e.step).padStart(2,'0')+' / '+e.phase.toUpperCase()+' / '+(e.method||'')+'\n'+JSON.stringify(e)).join('\n\n');$('exchange-phase').textContent=entry.phase==='discover'?'DISCOVERING A COMPATIBLE PEER':entry.phase==='call'?'CALLING '+entry.method.toUpperCase():entry.phase==='receipt'?'TYPED RECEIPT RETURNED':entry.phase.toUpperCase();}
function update(){const items=source.value?.items||[],rows=archive.value||[];$('exchange-source-state').textContent=JSON.stringify(items,null,2);$('exchange-archive-state').textContent=JSON.stringify(rows,null,2);$('exchange-source-count').textContent=items.filter(r=>r.delivered).length+' / '+items.length+' ACKNOWLEDGED';$('exchange-archive-count').textContent=rows.length+' SORTED RECORDS';$('exchange-send').disabled=!directory||!!active;$('exchange-reset').disabled=!!active;$('exchange-replay').disabled=!lastRequest||!!active;$('exchange-invalid').disabled=!directory||!!active;}
function pending(id){if(!completions.has(id)){let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});promise.catch(()=>{});completions.set(id,{promise,resolve,reject,settled:false});active++;update();}return completions.get(id);}
function settle(id,result,error){const p=completions.get(id);if(!p||p.settled)return;p.settled=true;active--;if(error){p.reject(error);log({phase:'failed',message:error.message});$('exchange-status').textContent=error.message;}else{p.resolve(result);log({phase:'complete',result});$('exchange-status').textContent='Acknowledged “'+result.word+'” · archive position '+result.position+' at receipt.';}update();}
function arrived(e){const r=e.detail;if(r.status!=='arrived'||!directory||disposed)return;
 if(r.to===source.id&&r.method==='add'){const p=pending(r.result.id);queue=queue.catch(()=>{}).then(async()=>{await sourcePeer.send('add',r.result,crypto.randomUUID());await p.promise;}).catch(error=>settle(r.result.id,null,error));}
 if(r.to===archive.id&&r.method==='add'&&r.from){archivePeer.send('acknowledge',r.result,crypto.randomUUID()).then(receipt=>settle(r.result.id,receipt.result)).catch(error=>settle(r.result.id,null,error));}
 update();}
stage.addEventListener('glyph-transfer',arrived);stage.addEventListener('glyph-state',update);stage.addEventListener('glyph-flow-error',e=>{$('exchange-status').textContent=e.detail.message;});
function attach(){if(directory||!window.glyphComponents)return;directory=window.glyphComponents;sourceEndpoint=directory.connect(source.dataset.glyphAgentAddress);archiveEndpoint=directory.connect(archive.dataset.glyphAgentAddress);sourcePeer=new M.Peer(sourceEndpoint,log);archivePeer=new M.Peer(archiveEndpoint,log);$('exchange-code').textContent='const me = directory.connect(myAddress);\nconst peers = me.discover(); // excludes self\nconst peer = peers.components.find(acceptsPacket);\nconst receipt = await me.call(peer, "add", packet, {requestId});\n// Receiver independently discovers acknowledge(...) and replies.\n// The form and WebMCP use directory.invoke(...) against the same methods.';$('exchange-status').textContent='Ready. Both components publish their own contracts.';update();}
document.addEventListener('glyph-components-ready',attach,{once:true});if(window.glyphComponents)queueMicrotask(attach);
async function submit(word){if(!directory)throw Error('Component directory is loading.');if(active)throw Error('Wait for the current exchange.');const packet={id:crypto.randomUUID(),word};C.validate(M.packet,packet);const own=sourceEndpoint.current(),completion=pending(packet.id);lastRequest={address:own.address,handle:own.handle,method:'add',payload:packet,requestId:crypto.randomUUID(),expectedRevision:own.revision};log({phase:'person-or-agent',to:own.address,method:'add',payload:packet});try{const receipt=await directory.invoke(lastRequest);await completion.promise;return receipt;}catch(error){settle(packet.id,null,error);throw error;}}
async function replay(){if(!lastRequest)throw Error('Send a word first.');const receipt=await directory.invoke(lastRequest);log({phase:'replay',requestId:receipt.requestId,result:receipt.result});$('exchange-status').textContent='Same receipt replayed · no second insertion or acknowledgement.';update();return receipt;}
async function invalid(){const own=sourceEndpoint.current(),before=C.canonical({source:source.value,archive:archive.value});try{await directory.invoke({address:own.address,handle:own.handle,method:'add',payload:{id:'invalid-word',word:42},requestId:crypto.randomUUID(),expectedRevision:own.revision});throw Error('Invalid input was accepted.');}catch(error){if(error.code!=='contract_mismatch')throw error;if(C.canonical({source:source.value,archive:archive.value})!==before)throw Error('Rejected input changed state.');log({phase:'contract-rejected',message:error.message});$('exchange-status').textContent='Rejected before transit: '+error.message+' Both components preserved.';return {rejected:true};}}
function reset(){if(active)throw Error('Wait for the exchange to finish.');stage.reset();completions.clear();trace.length=0;lastRequest=null;$('exchange-log').textContent='';$('exchange-status').textContent='Demo cleared. Existing studio data is separate.';update();}
$('exchange-form').onsubmit=async e=>{e.preventDefault();try{await submit($('exchange-word').value.trim());}catch(error){$('exchange-status').textContent=error.message;}finally{update();}};$('exchange-replay').onclick=()=>replay().catch(e=>$('exchange-status').textContent=e.message);$('exchange-invalid').onclick=()=>invalid().catch(e=>$('exchange-status').textContent=e.message);$('exchange-reset').onclick=reset;
window.glyphExchange={submit,replay,invalid,reset,settled:id=>completions.get(id)?.promise,get ready(){return !!directory;},get state(){return {source:source.value,archive:archive.value};},get trace(){return C.json(trace);},get active(){return active;}};
window.addEventListener('pagehide',()=>{disposed=true;for(const [id,p] of completions)if(!p.settled)settle(id,null,Error('Page disconnected.'));});update();
});
